// Sub-Agent: AI Doctor — подготовка пакета для агента + ПОЛ красных флагов (Фаза 2).
// ВАЖНО: в JS-regex \w НЕ матчит кириллицу — во всех паттернах ниже вместо \w используем [а-яёa-z0-9].
const sheetData = $input.first().json;
const triggerData = $('Главврач').first().json;
const binaryData = $('Главврач').first().binary;
const msg = triggerData.message?.caption || triggerData.message?.text || 'Посмотри на это фото.';

// L = «буква/цифра» (кириллица + латиница). Строим паттерны через шаблонные строки.
const L = '[а-яёa-z0-9]';
const rx = (s) => new RegExp(s.replace(/\\W/g, L), 'i');

const RED_FLAGS = [
  ['боль в груди с иррадиацией / одышка',
    rx('(груд|за\\s*грудин)[^.!?]{0,70}(отда[еёт]|иррадиир|в\\s*(лев\\W*\\s*)?руку|в\\s*(нижн\\W*\\s*)?челюст|в\\s*лопатк|в\\s*шею)|дав(ит|ящ\\W*|ление)[^.!?]{0,45}груд[^.!?]{0,45}(одышк|воздух|пот\\W|тошнот|слабост)|жж[её]т?[^.!?]{0,25}груд[^.!?]{0,45}(одышк|рук|челюст|пот)')],
  ['признаки инсульта',
    rx('(онемел\\W*|отнял\\W*|отня\\W*|перестал\\W*\\s*(слушать|двигать|шевелить|работать))[^.!?]{0,45}(рук|ног|половин\\W*\\s*тела|лиц)|перекос\\W*[^.!?]{0,20}(лиц|рот)|(речь|говор\\W*)[^.!?]{0,25}(спутан|невнятн|заплет|пропал)|(резко|внезапно)[^.!?]{0,25}не\\s*могу\\s*(говорить|двигать)|двоится\\s*в\\s*глаз|(внезапн\\W*|резк\\W*)[^.!?]{0,25}(слепот|потер\\W*\\s*зрени)')],
  ['громоподобная / worst-ever головная боль',
    rx('(сам\\W*\\s*(сильн\\W*|жутк\\W*|невыносим\\W*|ужасн\\W*)[^.!?]{0,25}(головн\\W*\\s*боль|голова))|громоподобн\\W*[^.!?]{0,20}голов|(внезапн\\W*|резк\\W*)[^.!?]{0,25}(сильнейш\\W*|нестерпим\\W*|как\\s*удар)[^.!?]{0,20}голов|голов\\W*\\s*боль[^.!?]{0,35}(в\\s*жизни|никогда\\s*так|как\\s*удар|громоподоб)|(сильнейш|нестерпим)\\W*\\s*(головн\\W*\\s*боль|голов)')],
  ['ЖКТ-кровотечение',
    rx('кофейн\\W*\\s*гущ|рвот\\W*[^.!?]{0,25}(кровь|с\\s*кровью|бур\\W|ч[ёе]рн)|ч[ёе]рн\\W*\\s*(стул|кал)(?![^.!?]{0,20}(активирован|уголь|железо|висмут|черник|св[её]кл))|мелена|(кровь|ал\\W*\\s*кров)[^.!?]{0,25}(в\\s*стуле|в\\s*кале|из\\s*(зад|прям\\W*\\s*кишк)|при\\s*дефекац|обильн)')],
  ['отёк гортани / удушье (анафилаксия)',
    rx('от[ёек]\\W*[^.!?]{0,20}(гортан|язык\\W|горл|губ)|(трудно|тяжело|не\\s*могу|стало\\s*трудно)\\s*(дышать|глотать|вдохнуть|сделать\\s*вдох)|горло\\s*(сжим|перекр|отекл|распух|сдавл)|распух\\W*[^.!?]{0,15}(лицо|горло|язык|губ)|крапивниц\\W*[^.!?]{0,25}(вс[её]\\s*тело|от[её]к|дыхан|горло)')],
  ['потеря сознания / судороги',
    rx('потер\\W*\\s*сознани|(упал|потерял\\W*|отключил\\W*)[^.!?]{0,20}(в\\s*обморок|сознание|отруб)|(перв\\W*\\s*раз|впервые)[^.!?]{0,20}судорог|судорог\\W*[^.!?]{0,25}(не\\s*прекращ|вс[её]\\s*тело|минут)|эпи?приступ|припадок\\s*(с|со|без)\\s*судорог')],
  ['внезапная нестерпимая боль в животе/боку/спине',
    rx('(внезапн\\W*|резк\\W*|остр\\W*)[^.!?]{0,15}(сильнейш\\W*|нестерпим\\W*|острейш\\W*|кинжальн\\W*|невыносим\\W*)[^.!?]{0,20}бол\\W*[^.!?]{0,20}(живот|поясниц|спин|бок|подреберь)|бол\\W*[^.!?]{0,12}(как\\s*удар\\s*ножом|будто\\s*разрыв)')],
  ['лихорадка + спутанность / ригидность шеи',
    rx('(температур\\W*|жар|лихорадк)[^.!?]{0,20}(3[89]|4[012])[^.!?]{0,55}(спутан|брежу|бред\\b|не\\s*могу\\s*согнуть\\s*шею|ригидн|светобоязн|сыпь\\s*не\\s*исчез)|не\\s*могу\\s*согнуть\\s*шею[^.!?]{0,25}(температур|жар|свет|голов)')],
];

const redFlag = { hit: false, matched: [] };
for (const [label, re] of RED_FLAGS) {
  if (re.test(msg)) { redFlag.hit = true; redFlag.matched.push(label); }
}

const result = {
  json: {
    medical_record: sheetData,
    user_message: msg,
    telegram_id: triggerData.message?.from?.id,
    chat_id: triggerData.message?.chat?.id,
    red_flag: redFlag,
    today: new Date(Date.now() + 10 * 3600 * 1000).toISOString().slice(0, 10),
  },
};
if (binaryData) result.binary = binaryData;
return [result];

let text = $json.output || "";

// 1. Превращаем <br> и <p> в нормальные текстовые переносы
text = text.replace(/<br\s*\/?>/gi, '\n');
text = text.replace(/<\/?p>/gi, '\n\n');

// 2. Спасаем жирный шрифт (Markdown в HTML)
text = text.replace(/\*\*(.*?)\*\*/g, '<b>$1</b>');
text = text.replace(/\*/g, '');

// 3. СПАСАЕМ МЕДИЦИНСКИЕ АНАЛИЗЫ (знаки < и >)
// Если после < идет пробел или цифра - это точно математика, а не тег
text = text.replace(/<(?=\s|[0-9])/g, '&lt;');
// Аналогично для знака >
text = text.replace(/(?<=\s|[0-9])>/g, '&gt;');

// 4. Оставляем только разрешенные теги Телеграма
const allowedTags = "b|strong|i|em|u|s|strike|del|a|code|pre";
const sanitizeRegex = new RegExp(`<\/?(?!(?:${allowedTags})\\b)[a-z0-9]+[^>]*>`, 'gi');
text = text.replace(sanitizeRegex, '');

// 5. 🏗 АВТО-БАЛАНСИРОВЩИК ТЕГОВ (Лечит ошибку Unmatched end tag)
const stack =[];
const tagRegex = /<\/?([a-z]+)[^>]*>/gi;
let match;

// Проходим по всем тегам в тексте
while ((match = tagRegex.exec(text)) !== null) {
  const tag = match[1].toLowerCase();
  const isClosing = match[0].startsWith('</');

  if (!isClosing) {
    // Если тег открылся - кладем его в "память"
    stack.push(tag);
  } else {
    // Если тег закрылся - убираем его из памяти
    const lastIndex = stack.lastIndexOf(tag);
    if (lastIndex !== -1) {
      stack.splice(lastIndex, 1); 
    }
  }
}

// Все теги, которые остались в "памяти" - нейросеть забыла закрыть!
// Аккуратно закрываем их в самом конце текста в обратном порядке
for (let i = stack.length - 1; i >= 0; i--) {
  text += `</${stack[i]}>`;
}

// 6. Убираем лишние пустые строки
text = text.replace(/\n{3,}/g, '\n\n');

return { 
  json: { 
    ...$json,
    output: text.trim() 
  } 
};

